// ── Two Pointers: two-sum in sorted array ───────────────────────
function twoSumSorted(nums, target) {
  let left = 0, right = nums.length - 1;
  while (left < right) {
    const sum = nums[left] + nums[right];
    if (sum === target) return [left, right];
    if (sum < target) left++;   // need more
    else              right--;  // need less
  }
  return [];
}
console.log(twoSumSorted([1, 2, 4, 6, 8], 10)); // [2, 4]

// ── Sliding Window: max sum subarray of length k ─────────────────
function maxSumSubarray(nums, k) {
  let windowSum = nums.slice(0, k).reduce((a, b) => a + b, 0);
  let maxSum = windowSum;
  for (let i = k; i < nums.length; i++) {
    windowSum += nums[i] - nums[i - k];
    maxSum = Math.max(maxSum, windowSum);
  }
  return maxSum;
}
console.log(maxSumSubarray([2, 1, 5, 1, 3, 2], 3)); // 9

// ── Fast/Slow Pointers: detect cycle in linked list ──────────────
function hasCycle(head) {
  let slow = head, fast = head;
  while (fast && fast.next) {
    slow = slow.next;
    fast = fast.next.next;
    if (slow === fast) return true;
  }
  return false;
}

// ── Prefix Sum: subarray sum equals k ────────────────────────────
function subarraySum(nums, k) {
  const counts = new Map([[0, 1]]);
  let prefix = 0, total = 0;
  for (const n of nums) {
    prefix += n;
    total += counts.get(prefix - k) ?? 0;
    counts.set(prefix, (counts.get(prefix) ?? 0) + 1);
  }
  return total;
}
console.log(subarraySum([1, 1, 1], 2)); // 2

// ── Backtracking: all subsets ────────────────────────────────────
function subsets(nums) {
  const result = [];
  function bt(start, current) {
    result.push([...current]);
    for (let i = start; i < nums.length; i++) {
      current.push(nums[i]);
      bt(i + 1, current);
      current.pop(); // unchoose
    }
  }
  bt(0, []);
  return result;
}
console.log(subsets([1, 2, 3]).length); // 8 (2^3)

// ── Merge Intervals ─────────────────────────────────────────────
function mergeIntervals(intervals) {
  intervals.sort((a, b) => a[0] - b[0]);
  const merged = [intervals[0]];
  for (const [start, end] of intervals.slice(1)) {
    const last = merged[merged.length - 1];
    if (start <= last[1]) last[1] = Math.max(last[1], end); // overlap
    else merged.push([start, end]);                         // gap
  }
  return merged;
}
console.log(mergeIntervals([[1,3],[2,6],[8,10],[15,18]]));
// [[1,6],[8,10],[15,18]]

// ── BFS: shortest path in unweighted graph ───────────────────────
function bfs(graph, start, end) {
  const visited = new Set([start]);
  const queue = [[start, 0]]; // [node, distance]
  while (queue.length) {
    const [node, dist] = queue.shift();
    if (node === end) return dist;
    for (const neighbour of graph[node] ?? []) {
      if (!visited.has(neighbour)) {
        visited.add(neighbour);
        queue.push([neighbour, dist + 1]);
      }
    }
  }
  return -1; // unreachable
}
const graph = { A: ['B', 'C'], B: ['D'], C: ['D'], D: [] };
console.log(bfs(graph, 'A', 'D')); // 2

// ── DFS: count islands in a grid ─────────────────────────────────
function numIslands(grid) {
  let count = 0;
  function dfs(r, c) {
    if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) return;
    if (grid[r][c] !== '1') return;
    grid[r][c] = '0'; // mark visited
    dfs(r+1,c); dfs(r-1,c); dfs(r,c+1); dfs(r,c-1);
  }
  for (let r = 0; r < grid.length; r++)
    for (let c = 0; c < grid[0].length; c++)
      if (grid[r][c] === '1') { count++; dfs(r, c); }
  return count;
}
console.log(numIslands([['1','1','0'],['0','1','0'],['0','0','1']])); // 2
